using System;using System.IO;using System.Text;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Globalization;
static class SentimentPlot {
 const int Width=2741,Height=795;static readonly Color Ink=Color.FromArgb(89,89,89),Red=Color.FromArgb(192,0,0),Old=Color.FromArgb(217,177,176),Count=Color.FromArgb(226,197,197);
 static readonly Color[] Colors={Color.FromArgb(217,150,148),Color.FromArgb(242,220,219),Color.FromArgb(238,236,225),Color.FromArgb(191,191,191),Color.FromArgb(185,205,229),Color.FromArgb(79,129,189)};
 static readonly string[] Labels={"低估值5bp以上","低估值3-5bp","估值±3bp","高估值3-5bp","高估值5-10bp","高估值10bp以上","情绪指数(新)-2026年8月9日开始","情绪指数（旧）","样本量N"};
 static Dictionary<string,object> Dict(object v){return(Dictionary<string,object>)v;}static object[] Arr(object v){var list=new List<object>();foreach(object x in(System.Collections.IEnumerable)v)list.Add(x);return list.ToArray();}static double Num(object v){return v==null?double.NaN:Convert.ToDouble(v,CultureInfo.InvariantCulture);}static double Field(Dictionary<string,object>d,string key){return d.ContainsKey(key)?Num(d[key]):double.NaN;}
 static Font Face(bool chinese,float size){return new Font(chinese?"SimSun":"Times New Roman",size,FontStyle.Regular,GraphicsUnit.Pixel);}
 static List<KeyValuePair<string,bool>> Runs(string text){var list=new List<KeyValuePair<string,bool>>();int start=0;for(int i=1;i<=text.Length;i++)if(i==text.Length||(text[i]>127)!=(text[start]>127)){list.Add(new KeyValuePair<string,bool>(text.Substring(start,i-start),text[start]>127));start=i;}return list;}
 static float Measure(Graphics g,string text,float size){float width=0;foreach(var r in Runs(text))using(var f=Face(r.Value,size))width+=g.MeasureString(r.Key,f,int.MaxValue,StringFormat.GenericTypographic).Width;return width;}
 static void Text(Graphics g,string text,float x,float y,float size,Color color){using(var brush=new SolidBrush(color)){foreach(var r in Runs(text))using(var f=Face(r.Value,size)){g.DrawString(r.Key,f,brush,new PointF(x,y),StringFormat.GenericTypographic);x+=g.MeasureString(r.Key,f,int.MaxValue,StringFormat.GenericTypographic).Width;}}}
 static void Series(Graphics g,List<PointF[]> segments,Color color,float thickness,bool smooth,bool circle,bool dash){using(var pen=new Pen(color,thickness)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;pen.LineJoin=LineJoin.Round;foreach(var points in segments){if(points.Length>1){if(smooth&&points.Length>2)g.DrawCurve(pen,points,.42f);else g.DrawLines(pen,points);}foreach(var p in points){if(circle){using(var fill=new SolidBrush(Red))using(var edge=new Pen(Color.FromArgb(147,56,54),1.5f)){g.FillEllipse(fill,p.X-4,p.Y-4,8,8);g.DrawEllipse(edge,p.X-4,p.Y-4,8,8);}}if(dash)using(var marker=new Pen(color,4))g.DrawLine(marker,p.X-7,p.Y,p.X+7,p.Y);}}}}
 static List<PointF[]> Points(object[] history,int start,int count,string key,float left,float top,float width,float height,double max){var segments=new List<PointF[]>();var list=new List<PointF>();for(int i=0;i<count;i++){double value=Field(Dict(history[start+i]),key);if(double.IsNaN(value)){if(list.Count>0){segments.Add(list.ToArray());list.Clear();}continue;}list.Add(new PointF(left+(i+.5f)*width/count,top+height-(float)(value/max*height)));}if(list.Count>0)segments.Add(list.ToArray());return segments;}
 public static void Render(string source,string target){var data=new JavaScriptSerializer{MaxJsonLength=16000000}.Deserialize<Dictionary<string,object>>(File.ReadAllText(source,Encoding.UTF8));var history=Arr(data["history"]);int count=Math.Min(200,history.Length),start=history.Length-count;if(count==0)throw new Exception("No chart data");
 using(var image=new Bitmap(Width,Height))using(var g=Graphics.FromImage(image)){g.Clear(Color.White);g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
 Text(g,"中信建投债务资本市场部",49,24,16,Color.Red);string title="债券市场一级情绪指数";Text(g,title,(Width-Measure(g,title,28))/2,18,28,Ink);
 float left=88,top=101,width=2574,height=577,bottom=top+height;double max=120;for(int i=start;i<history.Length;i++)foreach(string key in new[]{"index","oldIndex","n"}){double v=Field(Dict(history[i]),key);if(!double.IsNaN(v))max=Math.Max(max,Math.Ceiling(v/20)*20);}
 using(var grid=new Pen(Color.FromArgb(217,217,217),1.5f)){for(int i=0;i<=max/20;i++){float y=bottom-(float)(i*20/max*height);g.DrawLine(grid,left,y,left+width,y);string l=(i*20).ToString(),r=(i*20).ToString("F1");Text(g,l,left-12-Measure(g,l,17),y-10,17,Ink);Text(g,r,left+width+12,y-10,17,Ink);}}
 float step=width/count,barWidth=Math.Min(6,step*.46f);for(int i=0;i<count;i++){var h=Dict(history[start+i]);var values=Arr(h["bins"]);double baseline=0;for(int j=0;j<6;j++){double v=Num(values[j]);if(double.IsNaN(v))continue;float bh=(float)(v/max*height);using(var b=new SolidBrush(Colors[j]))g.FillRectangle(b,left+(i+.5f)*step-barWidth/2,bottom-(float)(baseline/max*height)-bh,barWidth,bh);baseline+=v;}}
 var fresh=Points(history,start,count,"index",left,top,width,height,max);Series(g,fresh,Red,3,true,true,false);Series(g,Points(history,start,count,"oldIndex",left,top,width,height,max),Old,4.5f,false,false,false);Series(g,Points(history,start,count,"n",left,top,width,height,max),Count,4.5f,false,false,true);
 for(int i=0;i<count;i++){double value=Field(Dict(history[start+i]),"index");if(double.IsNaN(value))continue;string label=value.ToString("F1",CultureInfo.InvariantCulture);float x=left+(i+.5f)*step,y=bottom-(float)(value/max*height);Text(g,label,x-Measure(g,label,14)/2,y-31,14,Color.FromArgb(64,64,64));}
 for(int i=0;i<count;i+=2){string raw=Convert.ToString(Dict(history[start+i])["date"]);DateTime date;if(!DateTime.TryParseExact(raw,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out date))continue;var state=g.Save();g.TranslateTransform(left+(i+.5f)*step-9,bottom+82);g.RotateTransform(-90);Text(g,date.ToString("yyyy/M/d",CultureInfo.InvariantCulture),0,0,17,Ink);g.Restore(state);}
 float legendWidth=0;foreach(var text in Labels)legendWidth+=40+8+Measure(g,text,18)+28;float legendX=(Width-legendWidth+28)/2,legendY=766;
 for(int j=0;j<Labels.Length;j++){Color color=j<6?Colors[j]:j==6?Red:j==7?Old:Count;if(j<6){using(var b=new SolidBrush(color))g.FillRectangle(b,legendX,legendY+2,40,11);}else{using(var pen=new Pen(color,j==6?3:4.5f)){pen.StartCap=LineCap.Round;pen.EndCap=LineCap.Round;g.DrawLine(pen,legendX,legendY+7,legendX+40,legendY+7);}if(j==6)using(var b=new SolidBrush(Red))g.FillEllipse(b,legendX+16,legendY+3,8,8);}
 Text(g,Labels[j],legendX+48,legendY-2,18,Ink);legendX+=48+Measure(g,Labels[j],18)+28;}
 image.Save(target,ImageFormat.Png);
 }}
}
